#[inline]
pub fn xmlRegFreeRegexp(mut regexp: xmlRegexpPtr) { unsafe {
    if regexp.is_null() {
        return;
    }

    let free = xmlFree.expect("non-null function pointer");
    let re = &mut *regexp;

    if !re.string.is_null() {
        free(re.string as *mut c_void);
    }

    let states = re.states;
    if !states.is_null() {
        let nb = re.nbStates;
        let mut i = 0;
        while i < nb {
            // SAFETY: `states` is non-null and points to an array of at least `nb` elements as required by the original code's invariants.
            xmlRegFreeState(*states.add(i as usize));
            i += 1;
        }
        free(states as *mut c_void);
    }

    let atoms = re.atoms;
    if !atoms.is_null() {
        let nb = re.nbAtoms;
        let mut i = 0;
        while i < nb {
            // SAFETY: `atoms` is non-null and points to an array of at least `nb` elements as required by the original code's invariants.
            xmlRegFreeAtom(*atoms.add(i as usize));
            i += 1;
        }
        free(atoms as *mut c_void);
    }

    if !re.counters.is_null() {
        free(re.counters as *mut c_void);
    }
    if !re.compact.is_null() {
        free(re.compact as *mut c_void);
    }
    if !re.transdata.is_null() {
        free(re.transdata as *mut c_void);
    }

    let string_map = re.stringMap;
    if !string_map.is_null() {
        let nb = re.nbstrings;
        let mut i = 0;
        while i < nb {
            // SAFETY: `string_map` is non-null and points to an array of at least `nb` elements as required by the original code's invariants.
            free(*string_map.add(i as usize) as *mut c_void);
            i += 1;
        }
        free(string_map as *mut c_void);
    }

    free(regexp as *mut c_void);
} }

